"use strict";
import { useQuery } from "@tanstack/react-query";
import { Contract } from "@ethersproject/contracts";
import { useAccount } from "hooks/useAccount";
import { useEthersProvider } from "hooks/useEthersProvider";
import { useMemo } from "react";
import ERC20_ABI from "uniswap/src/abis/erc20.json";
import NonfungiblePositionManagerJson from "@uniswap/v3-periphery/artifacts/contracts/NonfungiblePositionManager.sol/NonfungiblePositionManager.json";
import { getAbstractContracts } from "uniswap/src/constants/abstractContracts";
import { getContract } from "utilities/src/contracts/getContract";
import { useV2Pools, useV3Pools } from "./useSharedPoolData";
const { abi: NFTPositionManagerABI } = NonfungiblePositionManagerJson;
const MULTICALL3_ABI = [
  {
    inputs: [
      {
        components: [
          { name: "target", type: "address" },
          { name: "callData", type: "bytes" }
        ],
        name: "calls",
        type: "tuple[]"
      }
    ],
    name: "aggregate",
    outputs: [
      { name: "blockNumber", type: "uint256" },
      { name: "returnData", type: "bytes[]" }
    ],
    stateMutability: "payable",
    type: "function"
  }
];
const MULTICALL3_ADDRESS = "0xcA11bde05977b3631167028862bE2a173976CA11";
export function useV2Positions(chainId) {
  const account = useAccount();
  const provider = useEthersProvider({ chainId });
  const { data: v2Pools, isLoading: poolsLoading } = useV2Pools(chainId);
  const query = useQuery({
    queryKey: ["v2-positions", account.address, chainId, v2Pools?.length],
    queryFn: async () => {
      if (!account.address || !provider) return [];
      if (v2Pools.length === 0) return [];
      const multicallContract = getContract(MULTICALL3_ADDRESS, MULTICALL3_ABI, provider);
      if (!multicallContract) return [];
      const balanceInterface = new Contract(v2Pools[0].id, ERC20_ABI).interface;
      const calls = v2Pools.map((pool) => ({
        target: pool.id,
        callData: balanceInterface.encodeFunctionData("balanceOf", [account.address])
      }));
      const batchSize = 100;
      const results = [];
      for (let i = 0; i < calls.length; i += batchSize) {
        const batch = calls.slice(i, i + batchSize);
        try {
          const [, returnData] = await multicallContract.callStatic.aggregate(batch);
          results.push(...returnData);
        } catch (error) {
          console.error("Multicall batch failed:", error);
          results.push(...new Array(batch.length).fill("0x"));
        }
      }
      const positions = [];
      for (let i = 0; i < v2Pools.length; i++) {
        try {
          const balance = balanceInterface.decodeFunctionResult("balanceOf", results[i])[0];
          if (balance.gt(0)) {
            const pool = v2Pools[i];
            positions.push({
              type: "v2",
              poolAddress: pool.id,
              token0: pool.token0,
              token1: pool.token1,
              balance: balance.toString(),
              totalSupply: pool.totalSupply,
              reserve0: pool.reserve0,
              reserve1: pool.reserve1,
              reserveUSD: pool.reserveUSD,
              stable: pool.stable
            });
          }
        } catch (error) {
          continue;
        }
      }
      return positions;
    },
    enabled: !!account.address && !!provider && !poolsLoading && v2Pools.length > 0,
    refetchInterval: 3e4
    // Refetch every 30 seconds
  });
  return {
    data: query.data || [],
    isLoading: query.isLoading || poolsLoading
  };
}
export function useV3Positions(chainId) {
  const account = useAccount();
  const provider = useEthersProvider({ chainId });
  const contracts = getAbstractContracts(chainId);
  const { data: v3Pools, isLoading: poolsLoading } = useV3Pools(chainId);
  const query = useQuery({
    queryKey: ["v3-positions", account.address, chainId, v3Pools?.length],
    queryFn: async () => {
      if (!account.address || !provider || !contracts?.nonfungiblePositionManager) return [];
      const positionManager = getContract(
        contracts.nonfungiblePositionManager,
        NFTPositionManagerABI,
        provider
      );
      if (!positionManager) return [];
      const balance = await positionManager.balanceOf(account.address);
      if (balance.eq(0)) return [];
      const balanceCount = balance.toNumber();
      const multicallContract = getContract(MULTICALL3_ADDRESS, MULTICALL3_ABI, provider);
      if (!multicallContract) return [];
      const tokenIdCalls = [];
      for (let i = 0; i < balanceCount; i++) {
        tokenIdCalls.push({
          target: contracts.nonfungiblePositionManager,
          callData: positionManager.interface.encodeFunctionData("tokenOfOwnerByIndex", [account.address, i])
        });
      }
      let tokenIds = [];
      try {
        const [, tokenIdResults] = await multicallContract.callStatic.aggregate(tokenIdCalls);
        tokenIds = tokenIdResults.map((result) => {
          const decoded = positionManager.interface.decodeFunctionResult("tokenOfOwnerByIndex", result);
          return decoded[0].toString();
        });
      } catch (error) {
        console.error("Failed to fetch token IDs via multicall:", error);
        return [];
      }
      const positionCalls = tokenIds.map((tokenId) => ({
        target: contracts.nonfungiblePositionManager,
        callData: positionManager.interface.encodeFunctionData("positions", [tokenId])
      }));
      let positions = [];
      try {
        const batchSize = 50;
        const allPositionResults = [];
        for (let i = 0; i < positionCalls.length; i += batchSize) {
          const batch = positionCalls.slice(i, i + batchSize);
          const [, batchResults] = await multicallContract.callStatic.aggregate(batch);
          allPositionResults.push(...batchResults);
        }
        positions = tokenIds.map((tokenId, index) => {
          try {
            const positionResult = positionManager.interface.decodeFunctionResult("positions", allPositionResults[index]);
            if (!positionResult || positionResult.length === 0) {
              console.error(`No position result for token ${tokenId}`);
              return null;
            }
            const position = positionResult;
            if (!position || position.length < 12) {
              console.error(`Invalid position structure for token ${tokenId}, expected 12 fields but got ${position?.length}`);
              return null;
            }
            return {
              type: "v3",
              tokenId,
              // Based on NonfungiblePositionManager.sol, positions() returns:
              // (uint96 nonce, address operator, address token0, address token1, int24 tickSpacing, int24 tickLower, int24 tickUpper, uint128 liquidity, uint256 feeGrowthInside0LastX128, uint256 feeGrowthInside1LastX128, uint128 tokensOwed0, uint128 tokensOwed1)
              token0: position[2],
              // index 2: token0
              token1: position[3],
              // index 3: token1 
              tickSpacing: position[4],
              // index 4: tickSpacing
              tickLower: position[5],
              // index 5: tickLower
              tickUpper: position[6],
              // index 6: tickUpper
              liquidity: position[7]?.toString() || "0",
              // index 7: liquidity
              feeGrowthInside0LastX128: position[8]?.toString() || "0",
              // index 8: feeGrowthInside0LastX128
              feeGrowthInside1LastX128: position[9]?.toString() || "0",
              // index 9: feeGrowthInside1LastX128
              tokensOwed0: position[10]?.toString() || "0",
              // index 10: tokensOwed0
              tokensOwed1: position[11]?.toString() || "0"
              // index 11: tokensOwed1
            };
          } catch (error) {
            console.error(`Failed to decode position ${tokenId}:`, error);
            return null;
          }
        }).filter((position) => position !== null);
      } catch (error) {
        console.error("Failed to fetch position details via multicall:", error);
        return [];
      }
      const enrichedPositions = positions.map((position) => {
        const pool = v3Pools.find(
          (p) => p.token0.id.toLowerCase() === position.token0.toLowerCase() && p.token1.id.toLowerCase() === position.token1.toLowerCase() || p.token0.id.toLowerCase() === position.token1.toLowerCase() && p.token1.id.toLowerCase() === position.token0.toLowerCase()
        );
        return {
          ...position,
          poolData: pool || null
        };
      });
      return enrichedPositions;
    },
    enabled: !!account.address && !!provider && !!contracts?.nonfungiblePositionManager && !poolsLoading,
    refetchInterval: 3e4
    // Refetch every 30 seconds
  });
  return {
    data: query.data || [],
    isLoading: query.isLoading || poolsLoading
  };
}
export function useAllAbstractPositions(chainId) {
  const { data: v2Positions = [], isLoading: v2Loading } = useV2Positions(chainId);
  const { data: v3Positions = [], isLoading: v3Loading } = useV3Positions(chainId);
  const allPositions = useMemo(() => {
    return [...v2Positions, ...v3Positions];
  }, [v2Positions, v3Positions]);
  return {
    positions: allPositions,
    isLoading: v2Loading || v3Loading,
    v2Positions,
    v3Positions
  };
}
